// Exhaustive exact classification for 3 x m quadratic-pencil four-point avoidance.
// C++17, independent det3 subset-DP and det4 legal-move recursion.
#include <bits/stdc++.h>
using namespace std; using ll=long long;
struct Rat {ll p,q; Rat(ll a=0,ll b=1){if(b<0)a=-a,b=-b;ll g=gcd(llabs(a),b);p=a/g;q=b/g;} bool operator<(const Rat&z)const{return (__int128)p*z.q<(__int128)z.p*q;} string str()const{return to_string(p)+(q==1?"":"/"+to_string(q));}};
ll d3(const array<array<ll,3>,3>&a){return a[0][0]*(a[1][1]*a[2][2]-a[1][2]*(a[2][1]))-a[0][1]*(a[1][0]*a[2][2]-a[1][2]*a[2][0])+a[0][2]*(a[1][0]*a[2][1]-a[1][1]*a[2][0]);}
ll d4(const array<array<ll,4>,4>&a){array<int,4>p={0,1,2,3};ll z=0;do{ll v=1;int inv=0;for(int i=0;i<4;i++){v*=a[i][p[i]];for(int j=i+1;j<4;j++)inv+=p[i]>p[j];}z+=(inv&1)?-v:v;}while(next_permutation(p.begin(),p.end()));return z;}
struct Q {int mask;ll a,b;array<int,4>ids;};
struct Res {int root=0,safe=0,forb=0;vector<int>wins;array<int,22>by_size{},term{},by_g{};};
Res dp(int n,const vector<int>&fs){const int N=1<<n;vector<uint8_t>bad(N),g(N,255);for(int m:fs)bad[m]=1;for(int m=1;m<N;m++)if(!bad[m]){int bits=m;while(bits){int b=bits&-bits;bits-=b;if(bad[m^b]){bad[m]=1;break;}}}Res r;r.forb=fs.size();for(int m=N-1;m>=0;m--){if(bad[m])continue;int s=__builtin_popcount((unsigned)m);r.safe++;r.by_size[s]++;unsigned present=0;bool term=true;int bits=(N-1)^m;while(bits){int b=bits&-bits;bits-=b;int t=m|b;if(bad[t])continue;term=false;present|=1u<<g[t];}if(term)r.term[s]++;g[m]=__builtin_ctz(~present);r.by_g[g[m]]++;}r.root=g[0];for(int i=0;i<n;i++)if(g[1<<i]==0)r.wins.push_back(i);return r;}
Res rec(int n,const vector<Q>&qs,Rat l){vector<vector<int>>by_new(n);Res r;for(auto&z:qs){array<array<ll,4>,4>a{};for(int k=0;k<4;k++){int id=z.ids[k];ll x=id/3,y=id%3;a[k]={l.q*x*x+l.p*y*y,l.q*x,l.q*y,l.q};}if(d4(a))continue;r.forb++;for(int i:z.ids)by_new[i].push_back(z.mask^(1<<i));}const int N=1<<n;vector<int8_t>memo(N,-1);auto f=[&](auto&&self,int mask)->int{if(memo[mask]>=0)return memo[mask];r.safe++;int s=__builtin_popcount((unsigned)mask);r.by_size[s]++;unsigned present=0;bool term=true;for(int i=0;i<n;i++)if(!(mask>>i&1)){bool ok=true;for(int tri:by_new[i])if((mask&tri)==tri){ok=false;break;}if(!ok)continue;term=false;present|=1u<<self(self,mask|(1<<i));}if(term)r.term[s]++;int g=__builtin_ctz(~present);r.by_g[g]++;memo[mask]=g;return g;};r.root=f(f,0);for(int i=0;i<n;i++)if(memo[1<<i]==0)r.wins.push_back(i);return r;}
int main(int argc,char**argv){int width=argc>1?atoi(argv[1]):7,n=3*width;if(width<2||width>7)return 2;vector<Q>qs;set<Rat>ex;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)for(int k=j+1;k<n;k++)for(int l=k+1;l<n;l++){array<int,4>ids={i,j,k,l};array<array<ll,3>,3>A{},B{};for(int h=1;h<4;h++){ll x=ids[h]/3,y=ids[h]%3,u=i/3,v=i%3;A[h-1]={x*x-u*u,x-u,y-v};B[h-1]={y*y-v*v,x-u,y-v};}ll a=d3(A),b=d3(B);if(b)ex.insert(Rat(-a,b));qs.push_back({(1<<i)|(1<<j)|(1<<k)|(1<<l),a,b,ids});}Rat generic(1000003);if(ex.count(generic))return 3;vector<pair<string,Rat>>cases={{"generic",generic}};for(auto z:ex)cases.push_back({z.str(),z});cerr<<"width="<<width<<" cases="<<cases.size()<<" exceptions="<<ex.size()<<" quads="<<qs.size()<<"\n";cout<<"lambda\tgrundy\tsafe\tforbidden\twins\tmaximal\tsafe_by_size\n";long long total=0;for(auto [name,lam]:cases){vector<int>fs;for(auto&z:qs)if(z.a*lam.q+z.b*lam.p==0)fs.push_back(z.mask);Res a=dp(n,fs),b=rec(n,qs,lam);if(a.root!=b.root||a.safe!=b.safe||a.forb!=b.forb||a.wins!=b.wins||a.by_size!=b.by_size||a.term!=b.term||a.by_g!=b.by_g){cerr<<"MISMATCH "<<name<<"\n";return 1;}total+=a.safe;auto vs=[](const vector<int>&v){string s;for(int x:v){if(!s.empty())s+=",";s+=to_string(x);}return s.empty()?"-":s;};auto hist=[&](const array<int,22>&v){string s;for(int i=0;i<=n;i++)if(v[i]){if(!s.empty())s+=",";s+=to_string(i)+":"+to_string(v[i]);}return s;};cout<<name<<"\t"<<a.root<<"\t"<<a.safe<<"\t"<<a.forb<<"\t"<<vs(a.wins)<<"\t"<<hist(a.term)<<"\t"<<hist(a.by_size)<<"\n";cerr<<"."<<flush;}cerr<<"\nPASS: "<<cases.size()<<" cases, "<<total<<" safe states (each checked twice)\n";}
